#![allow(static_mut_refs, unsafe_op_in_unsafe_fn)]

#[allow(dead_code,unused_variables)]
mod __wasmc_canonical_transfer {
use std::alloc::{Layout,alloc_zeroed,dealloc};
#[link(wasm_import_module="wasmc:private/canonical-memory@1")]
unsafe extern "C" {
 fn read8(p:i32)->i32;fn read32(p:i32)->i32;fn read64(p:i32)->i64;
 fn write8(p:i32,v:i32);fn write32(p:i32,v:i32);fn write64(p:i32,v:i64);
 fn own_read8(p:i32)->i32;fn own_read32(p:i32)->i32;fn own_read64(p:i32)->i64;
 fn own_write8(p:i32,v:i32);fn own_write32(p:i32,v:i32);fn own_write64(p:i32,v:i64);
 fn own_memory_size()->i32;fn lib_memory_size()->i32;
 fn copy_to_lib(d:i32,s:i32,n:i32);fn copy_from_lib(d:i32,s:i32,n:i32);
}
fn add(p:u32,n:u32)->u32{p.checked_add(n).expect("pointer overflow")}
fn range(lib:bool,p:u32,n:u32,a:u32){assert!(a.is_power_of_two()&&p%a==0);let pages=unsafe{if lib{lib_memory_size()}else{own_memory_size()}} as u32 as u64;assert!((p as u64)+(n as u64)<=pages*65536);}
fn r(lib:bool,p:u32,n:u32)->u64{range(lib,p,n,1);unsafe{match n{1=>if lib{read8(p as i32) as u32 as u64}else{own_read8(p as i32) as u32 as u64},2=>r(lib,p,1)|(r(lib,add(p,1),1)<<8),4=>if lib{read32(p as i32) as u32 as u64}else{own_read32(p as i32) as u32 as u64},8=>if lib{read64(p as i32) as u64}else{own_read64(p as i32) as u64},_=>panic!("read width")}}}
fn w(lib:bool,p:u32,x:u64,n:u32){range(lib,p,n,1);unsafe{match n{1=>if lib{write8(p as i32,x as i32)}else{own_write8(p as i32,x as i32)},2=>{w(lib,p,x,1);w(lib,add(p,1),x>>8,1)},4=>if lib{write32(p as i32,x as i32)}else{own_write32(p as i32,x as i32)},8=>if lib{write64(p as i32,x as i64)}else{own_write64(p as i32,x as i64)},_=>panic!("write width")}}}
fn zero(lib:bool,p:u32,n:u32){range(lib,p,n,1);for i in 0..n{w(lib,add(p,i),0,1);}}
fn blit(from:bool,to:bool,s:u32,d:u32,n:u32){range(from,s,n,1);range(to,d,n,1);if from==to{if s!=d{for i in 0..n{w(to,add(d,i),r(from,add(s,i),1),1);}}}else{unsafe{if from{copy_from_lib(d as i32,s as i32,n as i32)}else{copy_to_lib(d as i32,s as i32,n as i32)}}}}
fn allocate(lib:bool,n:u32,a:u32)->u32{if n==0{return a;}let p=if lib{unsafe{realloc(0,0,a as i32,n as i32) as u32}}else{let l=Layout::from_size_align(n as usize,a as usize).unwrap();let p=unsafe{alloc_zeroed(l)};assert!(!p.is_null());value_allocation(p as usize as u32,n,a);p as usize as u32};range(lib,p,n,a);if lib{zero(true,p,n);}p}
struct Scratch{p:u32,l:Layout}
impl Scratch{fn new(n:u32,a:u32)->Self{let l=Layout::from_size_align(n.max(1) as usize,a as usize).unwrap();let p=allocate(false,n.max(1),a);Self{p,l}}}
impl Drop for Scratch{fn drop(&mut self){unsafe{value_scratch_drop(self.p);dealloc(self.p as usize as *mut u8,self.l);}}}

static mut VALUE_ACTIVE:Option<(u32,u32)>=None;
static mut VALUE_CAPTURE:bool=false;
static mut VALUE_ALLOCATIONS:Vec<(u32,u32,u32)>=Vec::new();
static mut VALUE_STAGING:Option<(u32,u32)>=None;
fn value_allocation(p:u32,n:u32,a:u32){unsafe{if VALUE_CAPTURE{VALUE_ALLOCATIONS.push((p,n,a));}}}
fn value_scratch_drop(p:u32){unsafe{if VALUE_CAPTURE{let i=VALUE_ALLOCATIONS.iter().position(|x|x.0==p).expect("scratch allocation lease");VALUE_ALLOCATIONS.swap_remove(i);}}}
fn value_begin(i:u32,d:u32){unsafe{assert!(VALUE_ACTIVE.is_none()&&!VALUE_CAPTURE&&VALUE_ALLOCATIONS.is_empty());VALUE_ACTIVE=Some((i,d));VALUE_CAPTURE=true;}}
fn value_call_begin(i:u32,p:u32,d:u32){unsafe{if VALUE_ACTIVE.is_none(){value_begin(i,d);}else{assert!(VALUE_ACTIVE==Some((i,d))&&VALUE_CAPTURE&&VALUE_STAGING==Some((p,d)));VALUE_STAGING=None;}}}
#[unsafe(no_mangle)]pub unsafe extern "C" fn __wasmc_value_stage_allocate(n:u32,a:u32)->u32{assert!(VALUE_CAPTURE&&VALUE_STAGING.is_some()&&a.is_power_of_two()&&a<=8);allocate(false,n,a)}
fn value_open(i:u32,pn:u32,pa:u32,dn:u32,da:u32)->u64{unsafe{value_begin(i,0);VALUE_STAGING=Some((0,0));let p=__wasmc_value_stage_allocate(pn,pa);let d=__wasmc_value_stage_allocate(dn,da);VALUE_ACTIVE=Some((i,d));VALUE_STAGING=Some((p,d));((d as u64)<<32)|(p as u64)}}
fn value_cancel(i:u32,d:u32){unsafe{assert!(VALUE_ACTIVE==Some((i,d))&&VALUE_CAPTURE&&VALUE_STAGING.is_some_and(|(_,q)|q==d));VALUE_STAGING=None;VALUE_CAPTURE=false;value_post(i,d);}}
fn value_ready(){unsafe{assert!(VALUE_CAPTURE);VALUE_CAPTURE=false;}}
fn value_post(i:u32,d:u32){unsafe{assert!(VALUE_ACTIVE==Some((i,d))&&!VALUE_CAPTURE&&VALUE_STAGING.is_none());VALUE_ACTIVE=None;let allocations=std::mem::take(&mut VALUE_ALLOCATIONS);for(p,n,a)in allocations{dealloc(p as usize as *mut u8,Layout::from_size_align(n as usize,a as usize).unwrap());}}}
#[unsafe(no_mangle)]pub unsafe extern "C" fn __wasmc_value_pending_allocations()->u32{VALUE_ALLOCATIONS.len() as u32}
#[link(wasm_import_module="wasmc:lib/wasmc-text@0.0.2")] unsafe extern "C" {#[link_name="cabi_realloc"]fn realloc(p:i32,n:i32,a:i32,m:i32)->i32;}
fn c_bool(s:u32,d:u32,from:bool,to:bool){range(from,s,1,1);range(to,d,1,1);let x=r(from,s,1);assert!(x<=1);w(to,d,x,1);}
fn c_u8(s:u32,d:u32,from:bool,to:bool){range(from,s,1,1);range(to,d,1,1);blit(from,to,s,d,1);}
fn c_s8(s:u32,d:u32,from:bool,to:bool){range(from,s,1,1);range(to,d,1,1);blit(from,to,s,d,1);}
fn c_u16(s:u32,d:u32,from:bool,to:bool){range(from,s,2,2);range(to,d,2,2);blit(from,to,s,d,2);}
fn c_s16(s:u32,d:u32,from:bool,to:bool){range(from,s,2,2);range(to,d,2,2);blit(from,to,s,d,2);}
fn c_u32(s:u32,d:u32,from:bool,to:bool){range(from,s,4,4);range(to,d,4,4);blit(from,to,s,d,4);}
fn c_s32(s:u32,d:u32,from:bool,to:bool){range(from,s,4,4);range(to,d,4,4);blit(from,to,s,d,4);}
fn c_u64(s:u32,d:u32,from:bool,to:bool){range(from,s,8,8);range(to,d,8,8);blit(from,to,s,d,8);}
fn c_s64(s:u32,d:u32,from:bool,to:bool){range(from,s,8,8);range(to,d,8,8);blit(from,to,s,d,8);}
fn c_f32(s:u32,d:u32,from:bool,to:bool){range(from,s,4,4);range(to,d,4,4);blit(from,to,s,d,4);}
fn c_f64(s:u32,d:u32,from:bool,to:bool){range(from,s,8,8);range(to,d,8,8);blit(from,to,s,d,8);}
fn c_char(s:u32,d:u32,from:bool,to:bool){range(from,s,4,4);range(to,d,4,4);let x=r(from,s,4);assert!(char::from_u32(x as u32).is_some());w(to,d,x,4);}
fn c_string(s:u32,d:u32,from:bool,to:bool){range(from,s,8,4);range(to,d,8,4);let p=r(from,s,4) as u32;let n=r(from,add(s,4),4) as u32;range(from,p,n,1);let mut v=Vec::with_capacity(n as usize);if from{if n!=0{unsafe{copy_from_lib(v.as_mut_ptr() as usize as i32,p as i32,n as i32);v.set_len(n as usize);}}}else{for i in 0..n{v.push(r(from,add(p,i),1) as u8);}}assert!(std::str::from_utf8(&v).is_ok());let q=allocate(!from,n,1);blit(from,!from,p,q,n);w(to,d,q as u64,4);w(to,add(d,4),n as u64,4);}
fn c0(s:u32,d:u32,from:bool,to:bool){range(from,s,8,4);range(to,d,8,4);let tag=r(from,s,1);assert!(tag<2);w(to,d,tag,1);match tag{0=>{},1=>{c_u32(add(s,4),add(d,4),from,to);},_=>unreachable!()};}
fn c1(s:u32,d:u32,from:bool,to:bool){range(from,s,8,4);range(to,d,8,4);let p=r(from,s,4) as u32;let n=r(from,add(s,4),4) as u32;let bytes=n.checked_mul(8).expect("list size");range(from,p,bytes,4);let q=allocate(!from,bytes,4);for i in 0..n{c_string(add(p,i*8),add(q,i*8),from,!from);}w(to,d,q as u64,4);w(to,add(d,4),n as u64,4);}
fn c2(s:u32,d:u32,from:bool,to:bool){range(from,s,8,4);range(to,d,8,4);let p=r(from,s,4) as u32;let n=r(from,add(s,4),4) as u32;let bytes=n.checked_mul(1).expect("list size");range(from,p,bytes,1);let q=allocate(!from,bytes,1);blit(from,!from,p,q,bytes);w(to,d,q as u64,4);w(to,add(d,4),n as u64,4);}
